  snapshot : String,
) -> (String, String, String, String) raise {
  match snapshot.split("\u0000").to_array() {
    [before, directory, ownership, yaml] if ownership == "install" ||
      ownership == "update" =>
      (
        before.to_owned(),
        directory.to_owned(),
        ownership.to_owned(),
        yaml.to_owned(),
      )
    _ => raise AdapterError("Invalid GitHub auth snapshot")
  }
}

///|
fn gh_token_source() -> String {
  for name in ["GH_TOKEN", "GITHUB_TOKEN"] {
    if @env.get_env_var(name) is Some(value) && value != "" {
      return name
    }
  }
  "gh-config-or-keyring"
}

///|
fn gh_document(
  snapshot : String,
  login : String,
  token : String,
) -> String raise {
  let (before, _, _, yaml) = gh_snapshot_parts(snapshot)
  let document = if yaml.trim() == "" {
    Json::empty_object()
  } else {
    let docs = @yaml.Yaml::load_from_string(yaml)
    guard docs.length() == 1 else {
      raise AdapterError("Invalid GitHub auth document")
    }
    docs[0].to_json()
  }
  guard document is Json::Object(_) else {
    raise AdapterError("Invalid GitHub auth mapping")
  }
  let users = Json::empty_object()
  set_field(users, login, { "oauth_token": token })
  let host = match field(document, "github.com") {
    None => Json::empty_object()
    Some(Json::Object(_) as host) => host
    _ => raise AdapterError("Invalid GitHub host mapping")
  }
  // Drop stale managed accounts while retaining unrelated per-host settings.
  set_field(host, "user", Json::string(login))
  set_field(host, "oauth_token", Json::string(token))
  set_field(host, "users", users)
  set_field(document, "github.com", host)
  let content = document.stringify() + "\n"
  before + "\n" + @utf8.encode(content).length().to_string() + "\n" + content
}

///|
async fn gh_deliver(state : Json, payload : String) -> Int32 {
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  @async.with_task_group(async fn(group) {
    let child = @process.spawn(
      group,
      "ssh",
      ssh_args(state, services=false) + [gh_delivery_script()],
      stdin=input,
      stdout=sink,
      stderr=sink,
    )
    writer.write(payload)
    writer.close()
    child.wait()
  })
}

///|
priv struct GhSequence {
  mut value : Int32
}

///|
let gh_sequence : GhSequence = { value: 0, }

///|
priv struct GhOperation {
  id : String
  workspace : String
}

///|
async fn GhOperation::record(
  self : GhOperation,
  status : String,
  phase? : String,
  code? : Int32,
  error_type? : String,
  duration_ms? : Double,
  inputs? : Json,
) -> Unit {
  save_diagnostic(
    "gh-auth",
    status,
    operation_id=self.id,
    workspace_id=self.workspace,
    phase?,
    exit_code?=code,
    error_type?,
    duration_ms?,
    gh_input?=inputs,
  )
}

///|
fn gh_delivery_status(code : Int32) -> String {
  match code {
    0 => "success"
    10 | 13 => "preserved-environment"
    11 => "preserved-authentication"
    12 => "preserved-modified"
    _ => "warning"
  }
}

///|
async fn gh_addon(state : Json) -> Unit {
  gh_sequence.value += 1
  let operation : GhOperation = {
    id: recording_run_id + ":gh:" + gh_sequence.value.to_string(),
    workspace: required(state, "workspaceId"),
  }
  let enabled = field(state, "ghAuth") == Some(Json::boolean(true))
  let inputs : Json = { "enabled": enabled, "hostname": "github.com" }
  if enabled && @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") {
    for name in ["GH_CONFIG_DIR", "XDG_CONFIG_HOME", "HOME"] {
      set_field(
        inputs,
        name,
        match @env.get_env_var(name) {
          Some(value) => Json::string(value)
          None => Json::null()
        },
      )
    }
    for name in ["GH_TOKEN", "GITHUB_TOKEN"] {
      set_field(
        inputs,
        name,
        Json::string(
          match @env.get_env_var(name) {
            None => "unset"
            Some("") => "empty"
            Some(_) => "present-value-withheld"
          },
        ),
      )
    }
  }
  operation.record(if enabled { "started" } else { "disabled" }, inputs~)
  if !enabled {
    return
  }
  let started = @env.now()
  let mut phase = "host-token"
  progress_message("gh-auth: running…")
  try {
    let code = @async.with_timeout(45000, async fn() {
      operation.record("started", phase~)
      let token = gh_host_token()
      operation.record("success", phase~)
      phase = "snapshot"
      operation.record("started", phase~)
      let (code, snapshot) = gh_capture(
        "ssh",
        ssh_args(state, services=false) + [gh_snapshot_script()],
      )
      operation.record(gh_delivery_status(code), phase~, code~)
      if code != 0 {
        if code == 10 || code == 13 {
          operation.record("preserved-environment", phase~, inputs={
            "remoteAuthenticationSource": if code == 10 {
              "GH_TOKEN"
            } else {
              "GITHUB_TOKEN"
            },
          })
        }
        return code
      }
      let (_, directory, ownership, _) = gh_snapshot_parts(snapshot)
      operation.record("selected", phase~, inputs={
        "remoteConfigDirectory": directory,
        "delivery": ownership,
      })
      phase = "host-account"
      operation.record("started", phase~)
      let login = gh_host_login(token)
      operation.record("success", phase~, inputs={
        "login": login,
        "authenticationSource": gh_token_source(),
      })
      phase = "merge"
      let payload = gh_document(snapshot, login, token)
      operation.record("success", phase~)
      phase = "delivery"
      operation.record("started", phase~)
      gh_deliver(state, payload)
    })
    let status = gh_delivery_status(code)
    operation.record(
      status,
      phase="complete",
      code~,
      duration_ms=(@env.now() - started).to_double(),
      error_type?=match code {
        0 | 10 | 11 | 12 | 13 => None
        20 => Some("remote_gh_missing")
        21 => Some("delivery_locked")
        23 => Some("incomplete_payload")
        _ => Some("delivery_failed")
      },
    )
    if status == "warning" {
      progress_message(
        "warning: GitHub authentication addon failed at " +
        phase +
        "; continuing",
      )
    } else {
      progress_message(
        "gh-auth: " + status + " (" + progress_timing(started) + ")",
      )
    }
  } catch {
    error => {
      let status = if error is @async.TimeoutError {
        "timeout"
      } else if @async.is_being_cancelled() {
        "cancelled"
      } else {
        "warning"
      }
      operation.record(
        status,
        phase~,
        error_type=match phase {
          "host-token" => "host_auth_unavailable"
          "host-account" => "host_account_unavailable"
          "merge" => "invalid_auth_document"
          _ => "delivery_failed"
        },
        duration_ms=(@env.now() - started).to_double(),
      )
      if status == "cancelled" {
        raise error
      }
      progress_message(
        "warning: GitHub authentication addon failed at " +
        phase +
        "; continuing",
      )
    }
  }
}
      Some(resolved) => output.write_string(resolved)
      None if required =>
        raise InvalidConfig(
          "\{location}: environment variable \{name} is not defined",
        )
      None => ()
    }
    remaining = suffix.to_owned()
  }
  output.write_string(remaining)
  output.to_string()
}

///|
pub fn resolve_settings(
  document : Json,
  recipe_id : String,
  lookup : (String) -> String?,
) -> Settings raise ConfigError {
  let common = object_field(document, "devsy", "orca.yaml")
  let recipes = match field(document, "environmentRecipes") {
    Some(Json::Array(items)) => items
    _ => raise InvalidConfig("orca.yaml.environmentRecipes must be an array")
  }
  let selected = recipes.filter(recipe => {
    field(recipe, "id") == Some(Json::string(recipe_id))
  })
  guard selected.length() == 1 else {
    raise InvalidConfig(
      "Expected exactly one environment recipe named \{recipe_id}",
    )
  }
  let specific = object_field(
    selected[0],
    "devsy",
    "environmentRecipes.\{recipe_id}",
  )
  let profile_name = match string_field(specific, "profile", "recipe.devsy") {
    Some(name) => Some(name)
    None => string_field(common, "profile", "devsy")
  }
  let profiles = object_field(common, "profiles", "devsy")
  let mut profile_location = "devsy.profiles"
  let profile = match profile_name {
    Some(raw_name) => {
      let name = interpolate(raw_name, lookup, "devsy.profile")
      profile_location = "devsy.profiles." + name
      match field(profiles, name) {
        Some(Json::Object(_) as value) => value
        _ => raise InvalidConfig("Unknown devsy profile")
      }
    }
    None => Json::empty_object()
  }
  let layers = [common, profile, specific]
  let mut command = ["devsy"]
  let mut home = None
  let mut context = None
  let mut build_ref = None
  let mut connection = None
  let mut codex_auth = false
  let args = []
  for index, layer in layers {
    let location = [
        "devsy",
        profile_location,
        "environmentRecipes." + recipe_id + ".devsy",
      ][index]
    if command_field(layer, location) is Some(raw) {
      let expanded = raw.mapi((argument_index, argument) => {
        interpolate(argument, lookup, "\{location}.command[\{argument_index}]")
      })
      let value = Json::empty_object()
      set_field(value, "command", Json::array(expanded.map(Json::string)))
      command = command_field(value, location).unwrap()
    }
    for
      pair in [
        ("home", string_field(layer, "home", location)),
        ("context", string_field(layer, "context", location)),
        ("buildRef", string_field(layer, "buildRef", location)),
        ("connection", string_field(layer, "connection", location)),
      ] {
      let (name, value) = pair
      if value is Some(raw) {
        let expanded = interpolate(raw, lookup, "\{location}.\{name}")
        match name {
          "home" => home = Some(expanded)
          "context" => context = Some(expanded)
          "buildRef" => build_ref = Some(expanded)
          _ => connection = Some(expanded)
        }
      }
    }
    for argument_index, argument in args_field(layer, location) {
      args.push(
        interpolate(argument, lookup, "\{location}.upArgs[\{argument_index}]"),
      )
    }
    let addons = object_field(layer, "addons", location)
    match field(addons, "codexAuth") {
      None => ()
      Some(Json::True) => codex_auth = true
      Some(Json::False) => codex_auth = false
      _ => raise InvalidConfig("\{location}.addons.codexAuth must be a boolean")
    }
  }
  let connection = match connection {
    Some("orca-server") => Server
    Some("ssh") => Ssh
    _ =>
      raise InvalidConfig(
        "devsy.connection must explicitly select orca-server or ssh",
      )
  }
  { connection, command, home, context, build_ref, up_args: args, codex_auth, }
}

